function tavsifla(x) {
    if (typeof x === "number") {
        return "son: " + x;
    } else if (typeof x === "string") {
        return "satr: " + x.length + " ta belgi";
    } else if (typeof x === "boolean") {
        return "mantiqiy: " + x;
    } else if (x === null) {
        return "null";
    } else if (Array.isArray(x)) {
        return "massiv: " + x.length + " ta element";
    }
    return "boshqa: " + typeof x;
}

