function bmiToifasi(vazn, boy) {
    const bmi = vazn / (boy * boy);
    let toifa;
    if (bmi < 18.5) {
        toifa = "kam vazn";
    } else if (bmi < 25) {
        toifa = "me'yor";
    } else if (bmi < 30) {
        toifa = "ortiqcha vazn";
    } else {
        toifa = "semizlik";
    }
    return `${bmi.toFixed(1)} → ${toifa}`;
}

